func parseOptionalTimestamp(c *gin.Context, name string) (*int64, bool) {
	raw, provided := c.GetQuery(name)
	if !provided {
		return nil, true
	}
	parsed, err := timeutil.Parse(raw)
	if err != nil {
		fail(c, http.StatusBadRequest, codeInvalidTimestamp, name+" must be an RFC 3339 timestamp")
		return nil, false
	}
	return &parsed, true
}
```

Derivation:

```go
// configChange is one audit entry derived from the append-only history of a
// single flag: the action is classified against the flag's own predecessor,
// never against the filtered result window.
type configChange struct {
	record store.ConfigRecord
	action string
	before *store.ConfigRecord
}

// deriveChanges walks the environment's records in storage order and
// classifies each one. A live record with no live predecessor is a creation,
// a live record following a live one is an update, and a tombstone is a
// deletion of the last live record.
func deriveChanges(records []store.ConfigRecord) []configChange {
	changes := make([]configChange, 0, len(records))
	lastLive := make(map[string]*store.ConfigRecord)
	for i := range records {
		record := &records[i]
		previous := lastLive[record.FlagKey]
		if record.Tombstone {
			changes = append(changes, configChange{record: *record, action: actionDeleted, before: previous})
			lastLive[record.FlagKey] = nil
			continue
		}
		action := actionCreated
		if previous != nil {
			action = actionUpdated
		}
		changes = append(changes, configChange{record: *record, action: action, before: previous})
		lastLive[record.FlagKey] = record
	}
	return changes
}
```

changed_fields:

```go
// changedFields lists the audited fields in the published fixed order:
// enabled, percentage, window.starts_at, window.ends_at. Creations and
// deletions list the non-empty fields of the config they introduce or
// remove; updates list the fields that actually differ.
func (c configChange) changedFields() []string {
	fields := make([]string, 0, 4)
	switch c.action {
	case actionCreated:
		return nonEmptyFields(&c.record, fields)
	case actionDeleted:
		return nonEmptyFields(c.before, fields)
	default:
		before := c.before
		after := &c.record
		if before.Enabled != after.Enabled {
			fields = append(fields, "enabled")
		}
		if before.Percentage != after.Percentage {
			fields = append(fields, "percentage")
		}
		if !sameInstant(before.StartsAt, after.StartsAt) {
			fields = append(fields, "window.starts_at")
		}
		if !sameInstant(before.EndsAt, after.EndsAt) {
			fields = append(fields, "window.ends_at")
		}
		return fields
	}
}

func nonEmptyFields(record *store.ConfigRecord, fields []string) []string {
	if record == nil {
		return fields
	}
	if record.Enabled {
		fields = append(fields, "enabled")
	}
	if record.Percentage != 0 {
		fields = append(fields, "percentage")
	}
	if record.StartsAt != nil {
		fields = append(fields, "window.starts_at")
	}
	if record.EndsAt != nil {
		fields = append(fields, "window.ends_at")
	}
	return fields
}

func sameInstant(a, b *int64) bool {
	if a == nil || b == nil {
		return a == b
	}
	return *a == *b
}
```

JSON rendering:

```go
func (c configChange) json() gin.H {
	var before, after any
	if c.before != nil {
		before = changeConfigJSON(c.before)
	}
	if c.action != actionDeleted {
		after = changeConfigJSON(&c.record)
	}
	return gin.H{
		"flag_key":       c.record.FlagKey,
		"version":        c.record.Version,
		"changed_at":     timeutil.Format(c.record.ChangedAt),
		"action":         c.action,
		"changed_fields": c.changedFields(),
		"before":         before,
		"after":          after,
	}
}

// changeConfigJSON renders the audited configuration snapshot: enabled,
// percentage and the time window, with empty window endpoints kept as null.
func changeConfigJSON(record *store.ConfigRecord) gin.H {
	return gin.H{
		"enabled":    record.Enabled,
		"percentage": record.Percentage,
		"window":     windowJSON(record.StartsAt, record.EndsAt),
	}
}
```

Wait — for deleted, before comes from `c.before` (the last live record). For created, before is nil. Good.

Hmm, one subtlety: for `deleted`, `c.before` — what if the tombstone's copied fields differ from the actual last live record? DeleteConfig copies from `current` which is the latest record at delete time. In the derivation, `lastLive[flag]` is the last non-tombstone record in the chain, which is exactly `current`. So they match. Good.

Edge: what if a tombstone appears with no preceding live record (data anomaly)? before = nil → changed_fields = [] and before: null. Acceptable defensive behavior; can't happen via the write API.

Store method in reads.go:

```go
// EnvironmentConfigHistory returns configuration records within environment
// across all flags, oldest first (changed_at, then insertion order),
// including tombstone records. When flagKey is non-empty only that flag's
// records are returned. The feed is read-only.
func (s *Store) EnvironmentConfigHistory(environment, flagKey string) ([]ConfigRecord, error) {
	query := `SELECT flag_key, environment, version, enabled, percentage, starts_at, ends_at, changed_at, tombstone
		 FROM config_history
		 WHERE environment = ?`
	args := []any{environment}
	if flagKey != "" {
		query += " AND flag_key = ?"
		args = append(args, flagKey)
	}
	query += " ORDER BY changed_at ASC, id ASC"
	rows, err := s.db.Query(query, args...)
	if err != nil {
		return nil, fmt.Errorf("query environment history: %w", err)
	}
	defer rows.Close()
	var records []ConfigRecord
	for rows.Next() {
		record, err := scanConfig(rows)
		if err != nil {
			return nil, err
		}
		records = append(records, record)
	}
	return records, rows.Err()
}
