   130			action := actionCreated
   131			if previous != nil {
   132				action = actionUpdated
   133			}
   134			changes = append(changes, configChange{record: *record, action: action, before: previous})
   135			lastLive[record.FlagKey] = record
   136		}
   137		return changes
   138	}
   139	
   140	// changedFields lists audited fields in the published fixed order: enabled,
   141	// percentage, window.starts_at, window.ends_at. Creations and deletions list
   142	// the non-empty fields of the configuration they introduce or remove;
   143	// updates list the fields that actually differ.
   144	func (change configChange) changedFields() []string {
   145		fields := make([]string, 0, 4)
   146		switch change.action {
   147		case actionCreated:
   148			return nonEmptyFields(&change.record, fields)
   149		case actionDeleted:
   150			return nonEmptyFields(change.before, fields)
   151		default:
   152			before := change.before
   153			after := &change.record
   154			if before.Enabled != after.Enabled {
   155				fields = append(fields, "enabled")
   156			}
   157			if before.Percentage != after.Percentage {
   158				fields = append(fields, "percentage")
   159			}
   160			if !sameInstant(before.StartsAt, after.StartsAt) {
   161				fields = append(fields, "window.starts_at")
   162			}
   163			if !sameInstant(before.EndsAt, after.EndsAt) {
   164				fields = append(fields, "window.ends_at")
   165			}
   166			return fields
   167		}
   168	}
   169	
   170	func nonEmptyFields(record *store.ConfigRecord, fields []string) []string {
   171		if record == nil {
   172			return fields
   173		}
   174		if record.Enabled {
   175			fields = append(fields, "enabled")
   176		}
   177		if record.Percentage != 0 {
   178			fields = append(fields, "percentage")
   179		}
   180		if record.StartsAt != nil {
   181			fields = append(fields, "window.starts_at")
   182		}
   183		if record.EndsAt != nil {
   184			fields = append(fields, "window.ends_at")
   185		}
   186		return fields
   187	}
   188	
   189	func sameInstant(a, b *int64) bool {
   190		if a == nil || b == nil {
   191			return a == b
   192		}
   193		return *a == *b
   194	}
   195	
   196	func (change configChange) json() gin.H {
   197		var before, after any
   198		if change.before != nil {
   199			before = changeConfigJSON(change.before)
   200		}
   201		if change.action != actionDeleted {
   202			after = changeConfigJSON(&change.record)
   203		}
   204		return gin.H{
   205			"flag_key":       change.record.FlagKey,
   206			"version":        change.record.Version,
   207			"changed_at":     timeutil.Format(change.record.ChangedAt),
   208			"action":         change.action,
   209			"changed_fields": change.changedFields(),
   210			"before":         before,
   211			"after":          after,
   212		}
   213	}
   214	
   215	// changeConfigJSON renders the audited configuration snapshot: enabled,
   216	// percentage and the time window, with empty window endpoints kept as null.
   217	func changeConfigJSON(record *store.ConfigRecord) gin.H {
   218		return gin.H{
   219			"enabled":    record.Enabled,
   220			"percentage": record.Percentage,
   221			"window":     windowJSON(record.StartsAt, record.EndsAt),
   222		}
   223	}

